do $do$
declare run_id bigint; rid bigint; a bigint; b bigint; r record; k int; isnew boolean;
begin
insert into public.companies(ticker,name,segment,size_tier,is_seed,is_hero,markets,exchange,country) values ($q$AML$q$,$q$Aston Martin Lagonda$q$,null,null,true,false,array[$q$LSE$q$]::text[],null,$q$GB$q$) on conflict (ticker) do update set is_seed=true, segment=excluded.segment, size_tier=excluded.size_tier, is_hero=excluded.is_hero, markets=case when cardinality(excluded.markets)>0 then excluded.markets else public.companies.markets end, exchange=coalesce(excluded.exchange, public.companies.exchange), country=coalesce(excluded.country, public.companies.country);
insert into public.companies(name,entity_type) select v.n,v.t from (values ($q$AMR GP$q$,$q$private_company$q$),($q$Aston Martin Aramco Formula One Team$q$,$q$private_company$q$),($q$Aston Martin Cognizant Formula One team$q$,$q$private_company$q$),($q$Aston Martin Performance Technologies$q$,$q$private_company$q$),($q$BERO$q$,$q$private_company$q$),($q$Champagne Bollinger$q$,$q$private_company$q$),($q$Classic Automobiles$q$,$q$private_company$q$),($q$ELEMIS$q$,$q$private_company$q$),($q$Geely$q$,$q$public_company$q$),($q$Glenfiddich$q$,$q$private_company$q$),($q$Lucid$q$,$q$public_company$q$),($q$Mercedes-Benz AG$q$,$q$public_company$q$),($q$Public Investment Fund$q$,$q$institution$q$),($q$St James Invest$q$,$q$private_company$q$),($q$Yew Tree Consortium$q$,$q$organization$q$),($q$Yew Tree Overseas Ltd$q$,$q$private_company$q$)) v(n,t) where not exists (select 1 from public.companies c where lower(c.name)=lower(v.n));
create temp table _q(i int primary key, t text) on commit drop;
insert into _q values (1,$q$Before the additional investment, the Yew Tree Consortium owned 28% of the issued share capital of the Company. The additional investment took the Consortium’s ownership to approximately 33%.$q$),(2,$q$During the year ended 31 December 2025 the Group incurred expenses of £0.4m due to AMR GP in relation to costs for supporting the sale of the significant portion of the Group’s investment holding in AMR GP.$q$),(3,$q$During the year ended 31 December 2025, AMR GP also purchased two used vehicles for £0.3m from a Group company of which £nil was outstanding as at 31 December 2025.$q$),(4,$q$During the year ended 31 December 2025, Classic Automobiles Inc. purchased a vehicle for £3.6m of which £1.1m was outstanding at 31 December 2025.$q$),(5,$q$During the year ended 31 December 2025, the Group incurred costs of £0.2m for safety testing services from companies within the Geely Holding Group of companies of which £nil was outstanding as at 31 December 2025.$q$),(6,$q$During the year ended 31 December 2025, the Group incurred expenses of £1.6m from Lucid, Inc relating to the implementation work for the technology purchased in 2023.$q$),(7,$q$Following shareholder approval in May 2025, this increased the Consortium’s shareholding to c. 33%, through the acquisition of 75 million new shares at a c. 7% premium to the closing price on 28 March 2025.$q$),(8,$q$Franz Reiner represents Mercedes-BenzAG, Scott Robertson represents the Public Investment Fund, Daniel Li represents Geely and Andrew McNaught represents Ernesto Bertarelli.$q$),(9,$q$Further enhanced by the proposed sale of the Aston Martin naming rights to AMR GP for a consideration of £50m in cash in Q1 2026$q$),(10,$q$Held via St James Invest SA$q$),(11,$q$In 2024, Aston Martin extended its long-term Sponsorship Arrangement until at least 2045, with the Naming Arrangements for AMR to use the ‘Aston Martin’ name in F1 until 2055 at the latest.$q$),(12,$q$In March, the Board approved the sale of the Group’s minority investment in the Aston Martin Aramco Formula One™ Team.$q$),(13,$q$In May 2025 the Group issued 75,000,000 ordinary shares through a non pre-emptive placing and retail offer to Yew Tree Consortium with net proceeds of £51.2m.$q$),(14,$q$In addition to the terms agreed in the Strategic Co-operation Agreement, the Group has a long-standing technical partnership with MBAG for the provision of engines, electrical architecture and entertainment systems.$q$),(15,$q$In addition, the Group incurred costs of £3.1m associated with engineering design on upcoming vehicle programmes from Aston Martin Performance Technologies Limited (“AMPT”) of which £1.2m is outstanding to AMPT at 31 December 2025.$q$),(16,$q$In early 2020, the Group entered into a sponsorship agreement, as amended in 2022, for a ten-year initial term under which the Racing Point Formula One™ team was re-launched as the Aston Martin Cognizant Formula One™ team with effect from the 2021 season, bringing an Aston Martin team back to the Formula One™ grid for the first time since 1960.$q$),(17,$q$Li Shufu (Geely) 142,530,859 14.08$q$),(18,$q$Mercedes-Benz AG 76,320,195 7.54$q$),(19,$q$Obtaining the circular and shareholder irrevocable undertakings relating to the sale of Naming Rights to AMR GP Holdings Limited (“AMR”) for £50m (‘the transaction’) in order to determine if there are any conditions which could prevent or delay the receipt of the cash.$q$),(20,$q$On 15 November 2023, the Group subscribed for shares in AMR GP Holdings Limited (“AMR GP”) by exercising its primary warrant option and subscribing for reward shares it was entitled to under the initial sponsorship term.$q$),(21,$q$On 2 July 2024 the Group entered a further agreement with MBAG relating to the future supply of engine units at a total cost of £63.2m.$q$),(22,$q$On 26 June 2023 the Company announced its intention to enter into a supply arrangement with Lucid to access Lucid’s powertrain components to promote the Company’s electrification strategy and long term growth.$q$),(23,$q$On 26 June 2023, the Aston Martin Lagonda Global Holdings plc confirmed a strategic supply arrangement with Lucid Group, Inc. (“Lucid”) providing the Group with access to select powertrain components for future BEV vehicles (collectively the “technology”).$q$),(24,$q$On 29 September 2025 the Group completed the sale of the significant portion of its shareholding in AMR GP Holdings Limited having early exercised an option to subscribe for additional equity for a fixed value.$q$),(25,$q$On 7 December 2020, the Company issued 224,657,287 shares to MBAG as consideration for access to the first tranche of powertrain and electronic architecture via a Strategic Cooperation Agreement (“SCA”).$q$),(26,$q$PIF are a substantial shareholder of the Group, and two members of the Group’s KMP and Non-Executive Directors are members of PIF’s KMP.$q$),(27,$q$Relationship Agreements between the Company and the Yew Tree Consortium dated 27 February 2020, MBAG dated 27 October 2020, the Public Investment Fund dated 29 July 2022 and Geely dated 18 May 2023 which govern the relationship between the Company and each of these shareholder groups$q$),(28,$q$Strategic arrangements with key partners, including Mercedes Benz AG, Lucid and Geely$q$),(29,$q$Successfully launched new brand partnerships and collaborations further expanding the impact of our brand globally, including BERO, Champagne Bollinger, Glenfiddich, ELEMIS$q$),(30,$q$The Company has four groups of significant shareholders, the Yew Tree Consortium, Mercedes-Benz AG, the Public Investment Fund and Geely.$q$),(31,$q$The Group has a Strategic Cooperation Agreement with MercedesBenz AG.$q$),(32,$q$The Group has a supply agreement with Lucid Group, Inc., which will help drive the Group’s electrification strategy and long-term growth.$q$),(33,$q$The Public Investment Fund 140,504,260 13.88$q$),(34,$q$The agreement provides the Company with access to a wide range of world-class technologies for the current generation of luxury vehicles and future derivatives.$q$),(35,$q$Under the amended agreement, the Company and MBAG will continue long-term strategic co-operation, supporting the delivery of current and future generation Aston Martin vehicles.$q$),(36,$q$Yew Tree Overseas Ltd 163,799,934 16.18$q$);
create temp table _e(n int, ty text, s text, g text, qs int[], sec text[], pct numeric, qual text, basis text, note text) on commit drop;
insert into _e values (1,$q$invests$q$,$q$Yew Tree Consortium$q$,$q$AML$q$,$q${7,30,1,13,27}$q$::int[],$q${p15,p96,p101,p211,p241}$q$::text[],33,$q$approximate$q$,$q$ownership$q$,null),(2,$q$sells_to$q$,$q$AML$q$,$q$AMR GP$q$,$q${9,3,19}$q$::int[],$q${p34,p223,p165}$q$::text[],null,null,null,null),(3,$q$partners$q$,$q$AML$q$,$q$BERO$q$,$q${29}$q$::int[],$q${p21}$q$::text[],null,null,null,null),(4,$q$partners$q$,$q$AML$q$,$q$Champagne Bollinger$q$,$q${29}$q$::int[],$q${p21}$q$::text[],null,null,null,null),(5,$q$partners$q$,$q$AML$q$,$q$Glenfiddich$q$,$q${29}$q$::int[],$q${p21}$q$::text[],null,null,null,null),(6,$q$partners$q$,$q$AML$q$,$q$ELEMIS$q$,$q${29}$q$::int[],$q${p21}$q$::text[],null,null,null,null),(7,$q$partners$q$,$q$AML$q$,$q$Mercedes-Benz AG$q$,$q${28,35,31}$q$::int[],$q${p74,p157,p177}$q$::text[],null,null,null,null),(8,$q$partners$q$,$q$AML$q$,$q$Lucid$q$,$q${28}$q$::int[],$q${p74}$q$::text[],null,null,null,null),(9,$q$partners$q$,$q$AML$q$,$q$Geely$q$,$q${28}$q$::int[],$q${p74}$q$::text[],null,null,null,null),(10,$q$invests$q$,$q$Mercedes-Benz AG$q$,$q$AML$q$,$q${30,18,8,27,25}$q$::int[],$q${p96,p156,p107,p241,p195}$q$::text[],null,null,null,null),(11,$q$invests$q$,$q$Geely$q$,$q$AML$q$,$q${30,8,17,27}$q$::int[],$q${p96,p107,p156,p241}$q$::text[],null,null,null,null),(12,$q$invests$q$,$q$Public Investment Fund$q$,$q$AML$q$,$q${30,8,33,26}$q$::int[],$q${p96,p107,p156,p223}$q$::text[],null,null,null,null),(13,$q$invests$q$,$q$AML$q$,$q$Aston Martin Aramco Formula One Team$q$,$q${12}$q$::int[],$q${p100}$q$::text[],null,null,null,null),(14,$q$invests$q$,$q$St James Invest$q$,$q$AML$q$,$q${10}$q$::int[],$q${p150}$q$::text[],null,null,null,null),(15,$q$supplies$q$,$q$Mercedes-Benz AG$q$,$q$AML$q$,$q${14,34,21}$q$::int[],$q${p157,p177,p195}$q$::text[],null,null,null,null),(16,$q$invests$q$,$q$Yew Tree Overseas Ltd$q$,$q$AML$q$,$q${36}$q$::int[],$q${p156}$q$::text[],16.18,$q$exact$q$,$q$ownership$q$,null),(17,$q$supplies$q$,$q$Lucid$q$,$q$AML$q$,$q${22,32,23,6}$q$::int[],$q${p158,p177,p195,p223}$q$::text[],null,null,null,null),(18,$q$partners$q$,$q$AML$q$,$q$Aston Martin Cognizant Formula One team$q$,$q${16}$q$::int[],$q${p158}$q$::text[],null,null,null,null),(19,$q$invests$q$,$q$AML$q$,$q$AMR GP$q$,$q${24,20,2}$q$::int[],$q${p189,p198,p223}$q$::text[],null,null,null,null),(20,$q$partners$q$,$q$AML$q$,$q$AMR GP$q$,$q${11}$q$::int[],$q${p227}$q$::text[],null,null,null,null),(21,$q$supplies$q$,$q$Aston Martin Performance Technologies$q$,$q$AML$q$,$q${15}$q$::int[],$q${p223}$q$::text[],null,null,null,null),(22,$q$supplies$q$,$q$Geely$q$,$q$AML$q$,$q${5}$q$::int[],$q${p223}$q$::text[],null,null,null,null),(23,$q$sells_to$q$,$q$AML$q$,$q$Classic Automobiles$q$,$q${4}$q$::int[],$q${p223}$q$::text[],null,null,null,null);
create or replace function pg_temp.nid(l text) returns bigint language sql as $f$ select id from public.companies where case l when $q$AML$q$ then ticker=$q$AML$q$ else lower(name)=lower(l) end order by id limit 1 $f$;
insert into public.agent_runs(agent_name,mode,target,model,cost_usd,status,review_status) values ('filings_extraction','batch',$q$AML Aston Martin Lagonda annual report 2025 (M14)$q$,'claude-sonnet-5-5 via Claude Code session',1.5103,'completed','unreviewed') returning id into run_id;
for r in select * from _e order by n loop a := pg_temp.nid(r.s); b := pg_temp.nid(r.g); if r.ty in ('competes','partners') and a > b then rid := a; a := b; b := rid; end if; isnew := false; rid := null; select id into rid from public.relationships where source_id=a and target_id=b and relationship_type=r.ty order by id limit 1; if rid is null then insert into public.relationships(source_id,target_id,relationship_type,exposure_pct,exposure_qualifier,exposure_basis,exposure_as_of,source_type,status,trust_status,run_id,as_of_date,note) values (a,b,r.ty,r.pct,r.qual,case when r.pct is null then 'none' else r.basis end,case when r.pct is null then null else $q$2025-12-31$q$::date end,$q$annual_report$q$,$q$staged$q$,null,run_id,$q$2025-12-31$q$::date,r.note) returning id into rid; isnew := true; end if; if isnew then for k in 1..array_length(r.qs,1) loop insert into public.evidence(relationship_id,document_url,section,quote,quote_found,published_at) select rid,null,r.sec[k],t,true,null from _q where i=r.qs[k]; end loop; end if; end loop;
end $do$;
